export function playSound(name = 'pickup') {
  const sounds = {
    pickup: '/pickup.wav',
  };
  const src = sounds[name] || sounds.pickup;
  const audio = new Audio(src);
  audio.volume = 0.5;
  audio.play().catch(() => {});
}

// Play a voice over audio clip generated by Bark
export function playVoice(filePath) {
  const audio = new Audio(filePath);
  audio.volume = 1.0;
  audio.play().catch(() => {});
}

// Speak the provided text using the browser's speech synthesis API
export function speakText(text) {
  if (typeof window === 'undefined' || !window.speechSynthesis) return;
  const utterance = new SpeechSynthesisUtterance(text);
  window.speechSynthesis.cancel();
  window.speechSynthesis.speak(utterance);
}
